-- GENERATED by tools/gen-text-filter-sql.mjs from engine/text-filter.js: do not edit by hand.
-- THRENYX word filter for text other players read: Alliance names, mottos and
-- member names. Run in the Supabase SQL editor after alliances.sql (and again
-- whenever the lists change).

create or replace function public.text_problem(p text)
returns text language plpgsql immutable set search_path = public as $$
declare
  raw text := lower(coalesce(p, ''));
  plain text;
  chunk text;
  toks text[] := '{}';
  t text;
  run text := '';
begin
  if raw ~ 'https?|www|[.,] *(com|net|org|gg|io|me|tv|ly|co|uk|xyz)\y|@|[0-9][0-9 ().-]{5,}[0-9]' then return 'No links, handles or phone numbers, please.'; end if;
  -- accents off, then the words, reading number-for-letter spellings inside a word
  plain := translate(raw, 'àáâãäåāèéêëēìíîïīòóôõöøōùúûüūñçýÿ', 'aaaaaaaeeeeeiiiiiooooooouuuuuncyy');
  foreach chunk in array regexp_split_to_array(plain, '[^a-z0-9$!|]+') loop
    chunk := regexp_replace(chunk, '^[!|]+|[!|]+$', '', 'g');
    if chunk !~ '[a-z]' then continue; end if;
    chunk := regexp_replace(translate(chunk, '01345789$!|', 'oieastbgsii'), '[^a-z]', '', 'g');
    if chunk <> '' then toks := toks || chunk; end if;
  end loop;
  foreach t in array toks loop
    if t ~ '^(snapchat|insta|instagram|discord|tiktok|whatsapp|telegram|kik|facebook|twitter|twitch|youtube|reddit|gmail|hotmail|yahoo|outlook|roblox)$' then return 'No social media or contact details, please.'; end if;
  end loop;
  -- spaced-out letters (f u c k) are read as one word
  foreach t in array toks || array[''] loop
    if length(t) = 1 then
      run := run || t;
    else
      if length(run) > 1 then toks := toks || run; end if;
      run := '';
    end if;
  end loop;
  foreach t in array toks loop
    if t ~ 'f+u+c+k+|s+h+i+t+|c+u+n+t+|n+i+g+g+e+r+|n+i+g+g+a+|f+a+g+g+o+t+|b+i+t+c+h+|w+h+o+r+e+|s+l+u+t+|d+i+l+d+o+|p+o+r+n+|p+e+n+i+s+|v+a+g+i+n+a+|j+i+z+z+|t+w+a+t+|m+o+t+h+e+r+f+|a+s+s+h+o+l+e+|h+i+t+l+e+r+|n+a+z+i+|k+k+k+|t+r+a+n+n+y+|k+i+k+e+|b+l+o+w+j+o+b+|h+a+n+d+j+o+b+|c+u+m+s+h+o+t+|o+r+g+a+s+m+|m+a+s+t+u+r+b+a+t+|b+o+n+e+r+|e+r+e+c+t+i+o+n+' or t ~ '^(a+s+s+|a+s+s+e+s+|a+r+s+e+|d+i+c+k+|d+i+c+k+s+|c+o+c+k+|c+o+c+k+s+|c+u+m+|s+e+x+|s+e+x+y+|r+a+p+e+|r+a+p+e+d+|r+a+p+i+s+t+|p+e+d+o+|p+e+d+o+p+h+i+l+e+|f+a+g+|f+a+g+s+|t+i+t+|t+i+t+s+|t+i+t+t+y+|b+o+o+b+|b+o+o+b+s+|n+u+d+e+|n+u+d+e+s+|n+a+k+e+d+|h+o+r+n+y+|s+p+i+c+|h+o+m+o+|h+o+e+|h+o+e+s+|p+u+s+s+y+|p+u+s+s+i+e+s+|w+a+n+k+|w+a+n+k+e+r+|c+h+i+n+k+|r+e+t+a+r+d+|r+e+t+a+r+d+s+|r+e+t+a+r+d+e+d+|b+a+s+t+a+r+d+|b+a+s+t+a+r+d+s+|d+a+m+n+|c+r+a+p+|p+i+s+s+|f+u+k+|f+c+k+|f+c+u+k+|s+t+f+u+|w+t+f+|o+m+f+g+|k+y+s+|m+i+l+f+|d+i+l+f+|n+s+f+w+|x+x+x+|t+h+o+t+|s+i+m+p+|i+n+c+e+l+|l+m+f+a+o+|a+n+a+l+)$' then return 'Please choose different words.'; end if;
  end loop;
  return null;
end $$;
grant execute on function public.text_problem(text) to authenticated;

-- Is the caller a guest? (the same definition as supabase/guest.sql)
create or replace function public.is_guest()
returns boolean language sql stable set search_path = public as $$
  select coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false)
     and not coalesce((auth.jwt() -> 'app_metadata' ->> 'threnyx_account')::boolean, false);
$$;

-- Founding an Alliance: the name and motto must pass; a member name that
-- doesn't shows as "Player".
create or replace function public.create_alliance(p_name text, p_motto text, p_faction text, p_player text)
returns public.alliances language plpgsql security definer set search_path = public as $$
declare a public.alliances; why text;
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if public.is_guest() then raise exception 'Save your profile to found an Alliance.'; end if;
  if exists (select 1 from alliance_members where user_id = auth.uid()) then raise exception 'Leave your Alliance first.'; end if;
  why := coalesce(public.text_problem(p_name), public.text_problem(p_motto));
  if why is not null then raise exception '%', why; end if;
  if exists (select 1 from alliances where lower(name) = lower(trim(p_name))) then raise exception 'That name is taken.'; end if;
  insert into alliances (name, motto, faction, leader) values (trim(p_name), coalesce(trim(p_motto), ''), p_faction, auth.uid()) returning * into a;
  insert into alliance_members (user_id, alliance_id, role, name) values (auth.uid(), a.id, 'leader', case when public.text_problem(p_player) is null then coalesce(nullif(trim(p_player), ''), 'Player') else 'Player' end);
  return a;
end $$;

create or replace function public.join_alliance(p_id uuid, p_player text)
returns public.alliances language plpgsql security definer set search_path = public as $$
declare a public.alliances;
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if public.is_guest() then raise exception 'Save your profile to join an Alliance.'; end if;
  if exists (select 1 from alliance_members where user_id = auth.uid()) then raise exception 'Leave your Alliance first.'; end if;
  select * into a from alliances where id = p_id for update;
  if not found then raise exception 'No such Alliance.'; end if;
  if a.member_count >= 30 then raise exception 'That Alliance is full (30).'; end if;
  insert into alliance_members (user_id, alliance_id, name) values (auth.uid(), p_id, case when public.text_problem(p_player) is null then coalesce(nullif(trim(p_player), ''), 'Player') else 'Player' end);
  update alliances set member_count = member_count + 1 where id = p_id returning * into a;
  return a;
end $$;

